INSERT INTO `media` VALUES (2,'탑건: 매버릭','1','조셉 코신스키','톰 크루즈, 마일스 텔러, 제니퍼 코넬리, 존 햄, 글렌 파월, 에드 해리스, 발 킬머','스카이댄스 미디어','파라마운트 픽처스','크리스토퍼 맥쿼리',NULL,'20220622',NULL,NULL,130,'12세 이상 관람가',NULL,'한순간의 실수도 용납되지 않는 하늘 위, 가장 압도적인 비행이 시작된다!  최고의 파일럿이자 전설적인 인물 매버릭(톰 크루즈)은 자신이 졸업한 훈련학교 교관으로 발탁된다. 그의 명성을 모르던 팀원들은 매버릭의 지시를 무시하지만 실전을 방불케 하는 상공 훈련에서 눈으로 봐도 믿기 힘든 전설적인 조종 실력에 모두가 압도된다.  매버릭의 지휘 아래 견고한 팀워크를 쌓아가던 팀원들에게 국경을 뛰어넘는 위험한 임무가 주어지자 매버릭은 자신이 가르친 동료들과 함께 마지막이 될지 모를 하늘 위 비행에 나서는데…',NULL,NULL,NULL,NULL,NULL,NULL),(3,'탑건','1','토니 스콧','톰 크루즈, 켈리 맥길리스, 발 킬머, 앤서니 에드워즈, 톰 스커릿','돈 심슨/제리 브룩하이머 필름스','파라마운트 픽처스','짐 캐시',NULL,'19870813',NULL,NULL,110,'15세 이상 관람가',NULL,'인도양에 배치된 미국 항공모함에서 발진한 F-14 두 대는 초계비행중 최신형 MiG-28과 조우한다. 상부에서는 자칫 실전이 벌어져 사태가 확전되는 것을 우려했기 때문에 절대로 먼저 발포하지 말 것을 명령하였고, 이렇게 서로 예의주의하며 신경전을 벌이던 중 미그기가 쿠거 대위가 모는 F-14에 레이더 락온을 걸어 지속적으로 위협하자 쿠거는 공포에 질려 공황발작을 일으킨다. 하지만 미첼 대위가 모는 F-14가 과감한 기동으로 미그를 견제비행하여 유혈사태 없이 이들을 쫓아버린다. 쿠거는 항공전대에서 최고의 파일럿이었지만 이 사건으로 전투기 파일럿이라는 업무에 부담감을 느껴 예편을 선택하고, 미첼 대위와 그의 파트너인 후방관제사(Radar interceptor Operator, RIO) 브래드쇼 중위는 쿠거를 대신해 캘리포니아 미라마(Miramar) 해군기지에 있는 탑건 스쿨에 입학한다. 이곳에서 미첼과 브래드쇼는 그들과 마찬가지로 각 항모 전단에서 선발된 미해군 최고의 파일럿들과 함께 공중전 훈련과 치열한 경쟁을 벌이게 되는데...',NULL,NULL,NULL,NULL,NULL,NULL),(10,'더 퍼스트 슬램덩크','1','이노우에 다케히코','','','(주)넥스트엔터테인먼트월드(NEW)^',NULL,NULL,'20230104',NULL,NULL,124,'12세이상관람가','애니메이션',NULL,'20228555',3895172,2,'20230309',NULL,NULL),(11,'타이타닉','1','제임스 카메론','레오나르도 디카프리오^케이트 윈슬렛','파라마운트 픽쳐스^','월트디즈니컴퍼니코리아 유한책임회사^씨네힐^이십세기폭스코리아(주)^',NULL,NULL,'19980220',NULL,NULL,194,'15세이상관람가','드라마^멜로/로맨스^액션',NULL,'19980074',857407,3,'20230221',NULL,NULL),(12,'아바타: 물의 길','1','제임스 카메론','조 샐다나^샘 워싱턴^시고니 위버^스티븐 랭^케이트 윈슬렛','','월트디즈니컴퍼니코리아 유한책임회사^',NULL,NULL,'20221214',NULL,NULL,192,'12세이상관람가','액션^어드벤처^SF^스릴러',NULL,'20225061',10772842,9,'20230227',NULL,NULL),(13,'교섭','1','임순례','황정민^현빈^강기영','(주)영화사수박^원테이크필름^','플러스엠 엔터테인먼트^',NULL,NULL,'20230118',NULL,NULL,108,'12세이상관람가','드라마',NULL,'20190808',1709122,6,'20230215',NULL,NULL),(14,'영웅','1','윤제균','정성화^김고은^나문희^조재윤^배정남^이현우^박진주^권